                    if 0 <= r < h and 0 <= c < w:
                        paint_cells.append((r, c))
        if paint_cells:
            ops.append(int(mainc))
            sels.append(sel_of(sorted(set(paint_cells))))

    ops.append(34)
    sels.append([0, 0, ho - 1, wo - 1])
    return ops, sels


